style.css:
@-moz-document domain("youtube.com") {
/* Thay đổi hình nền cho toàn bộ trang */
    body, 
    ytd-app, 
    #page-manager, 
    #content {
        background-image: url('https://images.unsplash.com/photo-1542273917363-3b1817f69a2d?q=80&w=2074&auto=format&fit=crop') !important;
        background-size: cover !important;
        background-attachment: fixed !important;
        background-position: center !important;
        background-repeat: no-repeat !important;
    }

    /* Làm trong suốt các khoảng nền trắng để lộ hình rừng thông */
    ytd-masthead, 
    #background.ytd-masthead,
    ytd-page-manager,
    ytd-browse,
    ytd-watch-flexy,
    #columns.ytd-watch-flexy,
    #primary.ytd-watch-flexy,
    #secondary.ytd-watch-flexy,
    #guide-content.ytd-app,
    ytd-guide-renderer,
    #contentContainer.app-header-layout,
    #page-manager ytd-search {
        background: transparent !important;
        background-color: transparent !important;
    }

    /* Thêm một lớp nền mờ tối cho các block chứa video để dễ đọc chữ */
    ytd-rich-grid-media, 
    ytd-video-renderer, 
    ytd-compact-video-renderer,
    #watch-card-selection,
    .ytd-watch-metadata {
        background: rgba(0, 0, 0, 0.4) !important;
        padding: 10px !important;
        border-radius: 8px !important;
    }

    /* Đổi màu chữ sang trắng để nổi bật trên nền rừng */
    #video-title, 
    span, 
    h1, 
    h2, 
    h3, 
    yt-formatted-string {
        color: #ffffff !important;
    }
}
